#!/usr/bin/env node
/**
 * Sync portal .env files from the canonical Docker env (.env.docker).
 *
 * Usage:
 *   npm run env:sync
 *   node scripts/env/sync-portal-env.mjs --from .env.docker
 *   node scripts/env/sync-portal-env.mjs --dry-run
 *
 * Writes (gitignored):
 *   Isara-patient-portal/.env
 *   Isara-doctor-portal/.env
 *   Izara-jitsi-server/.env
 *   .env  (root — Vitest / Playwright)
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const args = process.argv.slice(2);
const dryRun = args.includes('--dry-run');
const fromIdx = args.indexOf('--from');
const sourceFile = path.join(
  repoRoot,
  fromIdx !== -1 && args[fromIdx + 1] ? args[fromIdx + 1] : '.env.docker',
);

function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`❌ Source not found: ${filePath}`);
    console.error('   Copy .env.docker.example → .env.docker and fill secrets first.');
    process.exit(1);
  }
  const map = new Map();
  for (const line of fs.readFileSync(filePath, 'utf8').split('\n')) {
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    const eq = t.indexOf('=');
    if (eq <= 0) continue;
    map.set(t.slice(0, eq).trim(), t.slice(eq + 1));
  }
  return map;
}

function pick(src, keys) {
  const out = {};
  for (const k of keys) {
    if (src.has(k)) out[k] = src.get(k);
  }
  return out;
}

function renderEnv(title, rows, extra = {}) {
  const lines = [
    `# ${title}`,
    `# Generated by: npm run env:sync`,
    `# Source: ${path.basename(sourceFile)} — re-run after changing shared secrets/keys`,
    '',
  ];
  const merged = { ...rows, ...extra };
  for (const [k, v] of Object.entries(merged)) {
    lines.push(`${k}=${v}`);
  }
  lines.push('');
  return lines.join('\n');
}

function writeEnv(relPath, content) {
  const full = path.join(repoRoot, relPath);
  if (dryRun) {
    console.log(`[dry-run] Would write ${relPath} (${content.split('\n').length} lines)`);
    return;
  }
  fs.writeFileSync(full, content, 'utf8');
  console.log(`✅ ${relPath}`);
}

const src = parseEnvFile(sourceFile);
const dbPass = src.get('DB_PASSWORD') || src.get('POSTGRES_PASSWORD') || 'postgres';
const jwt = src.get('JWT_SECRET') || 'izara-jwt-secret-key-phase1-2026-min-32-chars';
const gemini = src.get('GEMINI_API_KEY') || 'xxxxx';
const googleClient = src.get('GOOGLE_CLIENT_ID') || src.get('VITE_GOOGLE_CLIENT_ID') || '';
const googleMaps = src.get('GOOGLE_MAPS_API_KEY') || src.get('VITE_GOOGLE_MAPS_API_KEY') || '';
const googleSpeech = src.get('GOOGLE_SPEECH_API_KEY') || src.get('VITE_GOOGLE_SPEECH_API_KEY') || '';
const googleCal = src.get('VITE_GOOGLE_CALENDAR_API_KEY') || googleSpeech;
const recordingKey = src.get('RECORDING_ENCRYPTION_KEY') || '';
const jibriSecret = src.get('JIBRI_WEBHOOK_SECRET') || '';

const sharedDb = {
  DB_HOST: 'localhost',
  DB_PORT: '5433',
  DB_NAME: src.get('DB_NAME') || 'izara_phase1',
  DB_USER: src.get('DB_USER') || 'postgres',
  DB_PASSWORD: dbPass,
  DATABASE_URL: `postgresql://postgres:${encodeURIComponent(dbPass)}@localhost:5433/izara_phase1`,
  USE_POSTGRESQL: 'true',
};

const patientEnv = renderEnv('Izara Patient Portal — npm dev (backend :3004, Vite :3005)', {
  NODE_ENV: 'development',
  PORT: '3004',
  VITE_API_URL: 'http://localhost:3005',
  VITE_AUTH_PORTAL_URL: 'http://localhost:3005/auth',
  VITE_PATIENT_URL: 'http://localhost:3005/home',
  VITE_WEBSOCKET_URL: 'ws://localhost:3005/ws',
  MEETING_SERVER_URL: 'http://localhost:3020',
  VITE_MEETING_SERVER_URL: 'http://localhost:3020',
  ...sharedDb,
  GCP_PROJECT_ID: src.get('GCP_PROJECT_ID') || 'izara-telemedicine',
  VITE_GCP_REGION: src.get('VITE_GCP_REGION') || 'asia-southeast1',
  GOOGLE_CLIENT_ID: googleClient,
  VITE_GOOGLE_CLIENT_ID: googleClient,
  VITE_GOOGLE_MAPS_API_KEY: googleMaps,
  VITE_GOOGLE_MAPS_MAP_ID: src.get('VITE_GOOGLE_MAPS_MAP_ID') || '',
  VITE_GOOGLE_CALENDAR_API_KEY: googleCal,
  VITE_GOOGLE_MEET_API_KEY: googleCal,
  GEMINI_API_KEY: gemini,
  GEMINI_MODEL: src.get('GEMINI_MODEL') || 'gemini-3.1-flash-lite',
  JITSI_DOMAIN: src.get('JITSI_DOMAIN') || 'meet.jit.si',
  JITSI_APP_ID: src.get('JITSI_APP_ID') || 'izara-telemedicine',
  VITE_JITSI_APP_ID: src.get('VITE_JITSI_APP_ID') || 'izara-telemedicine',
  JWT_SECRET: jwt,
});

const doctorEnv = renderEnv('Izara Doctor Portal — npm dev (Vite :3010, auth :3011, API :3009)', {
  NODE_ENV: 'development',
  AUTH_PORT: '3011',
  VITE_API_URL: 'http://localhost:3010',
  VITE_AUTH_URL: 'http://localhost:3011/auth',
  VITE_DOCTOR_URL: 'http://localhost:3010',
  VITE_WEBSOCKET_URL: 'ws://localhost:3011/ws',
  MEETING_SERVER_URL: 'http://localhost:3020',
  VITE_MEETING_SERVER_URL: 'http://localhost:3020',
  CORS_ORIGINS:
    'http://localhost:3010,http://localhost:3005,http://localhost:3011,http://localhost:3020',
  ...sharedDb,
  GCP_PROJECT_ID: src.get('GCP_PROJECT_ID') || 'izara-telemedicine',
  VITE_GCP_REGION: src.get('VITE_GCP_REGION') || 'asia-southeast1',
  GOOGLE_CLIENT_ID: googleClient,
  VITE_GOOGLE_CLIENT_ID: googleClient,
  VITE_GOOGLE_CALENDAR_API_KEY: googleCal,
  VITE_GOOGLE_MEET_API_KEY: googleCal,
  GOOGLE_SPEECH_API_KEY: googleSpeech,
  GEMINI_API_KEY: gemini,
  VITE_GEMINI_API_KEY: gemini,
  GEMINI_MODEL: src.get('GEMINI_MODEL') || 'gemini-3.1-flash-lite',
  VITE_GEMINI_MODEL: src.get('GEMINI_MODEL') || 'gemini-3.1-flash-lite',
  JITSI_DOMAIN: src.get('JITSI_DOMAIN') || 'meet.jit.si',
  VITE_JITSI_DOMAIN: src.get('JITSI_DOMAIN') || 'meet.jit.si',
  JITSI_APP_ID: src.get('JITSI_APP_ID') || 'izara-telemedicine',
  JWT_SECRET: jwt,
});

const meetingEnv = renderEnv('Izara Meeting Server — npm dev (:3020)', {
  NODE_ENV: 'development',
  PORT: '3020',
  ...sharedDb,
  JITSI_DOMAIN: src.get('JITSI_DOMAIN') || 'meet.jit.si',
  JITSI_APP_ID: src.get('JITSI_APP_ID') || 'izara-telemedicine',
  GOOGLE_SPEECH_API_KEY: googleSpeech,
  GOOGLE_CLOUD_SPEECH_API_KEY: googleSpeech,
  GEMINI_API_KEY: gemini,
  GEMINI_MODEL: src.get('GEMINI_MODEL') || 'gemini-3.1-flash-lite',
  JWT_SECRET: jwt,
  JWT_EXPIRES_IN: src.get('JWT_EXPIRES_IN') || '24h',
  CORS_ORIGINS:
    'http://localhost:3005,http://localhost:3010,http://localhost:3020,http://127.0.0.1:3005,http://127.0.0.1:3010,http://127.0.0.1:3020',
  RECORDING_ENCRYPTION_KEY: recordingKey,
  JIBRI_WEBHOOK_SECRET: jibriSecret,
  RECORDINGS_DIR: './recordings',
});

const rootEnv = renderEnv('Isara Anywhere root — Vitest / Playwright / gate scripts', {
  ...pick(src, [
    'GCP_PROJECT_ID',
    'VITE_GCP_REGION',
    'GOOGLE_CLIENT_ID',
    'GOOGLE_CLIENT_SECRET',
    'GEMINI_API_KEY',
    'GEMINI_MODEL',
    'JWT_SECRET',
    'RECORDING_ENCRYPTION_KEY',
    'JIBRI_WEBHOOK_SECRET',
  ]),
  ...sharedDb,
  POSTGRES_USER: 'postgres',
  POSTGRES_PASSWORD: dbPass,
  POSTGRES_DB: 'izara_phase1',
  PATIENT_URL: 'http://localhost:3005',
  DOCTOR_URL: 'http://localhost:3010',
  MEETING_URL: 'http://localhost:3020',
  TEST_ENV: 'local',
});

console.log(`\n📋 Sync portal .env from ${path.relative(repoRoot, sourceFile)}\n`);
writeEnv('Isara-patient-portal/.env', patientEnv);
writeEnv('Isara-doctor-portal/.env', doctorEnv);
writeEnv('Izara-jitsi-server/.env', meetingEnv);
writeEnv('.env', rootEnv);
console.log(dryRun ? '\n(dry-run — no files written)\n' : '\nDone. Start npm dev in each portal folder.\n');
